                                                                        trace.statement("cVar9 = FUN_18026ee60(0);");
                                                                        if (trace.checked_condition("if (cVar9 != '\\0')", [&]() -> bool { return static_cast<bool>(cVar9 != '\0'); })) {
                                                                            trace.statement("FUN_180280d00(");
                                                                            trace.statement("\"Puts the built-in list back: addons (empty), lua/bin (hidden),\\nlua/*.lua (hidden).\\n\\nThe last one is precise on purpose -- a stock garrysmod/lua holds\\nonly directories, so a loose .lua sitting there is always\\nsomething that was put there (a dump, an executor\\'s scratch file).\\nA broad lua/* would swallow the stock folders instead and make the\\nwhole tree vanish, which is far louder than the files it hides.\\n\\nReplaces the current list, so a config saved with its own rules\\ngets the defaults back only when you press this.\"");
                                                                            trace.statement(");");
                                                                        }
                                                                        trace.statement("fStack_1a1c = *(float *)((longlong)&DAT_1803dca30 + lVar49 + 4) * 0.75;");
                                                                        trace.statement("local_1a28 = *(undefined1 (*) [12])(&DAT_1803dca28 + lVar49);");
                                                                        trace.statement("FUN_1802aabb0(local_1a28,");
                                                                        trace.statement("\"Paths are relative to garrysmod/, and one rule covers every way\\nof spelling the same folder -- \\\"lua/bin\\\" catches all three of\\nfile.Find(\\\"lua/bin/*\\\",\\\"MOD\\\"), file.Find(\\\"bin/*\\\",\\\"LUA\\\") and\\nfile.Find(\\\"garrysmod/lua/bin/*\\\",\\\"base_path\\\").\\nUse data/... for the data folder, @root/... for what really is\\noutside garrysmod/ (bin/, sourceengine/, the exe).\"");
                                                                        trace.statement(");");
                                                                        trace.statement("FUN_1802afb40();");
                                                                        trace.statement("FUN_18019a460(\"Beyond the file library\",0);");
                                                                        trace.statement("local_1678 = 4;");
