                                                                        trace.statement("FUN_1802aabb0(&DAT_1803dca18 + (longlong)DAT_1803fb24c * 200,&DAT_1803431ac,");
                                                                        trace.statement("\"Beyond the file library\");");
                                                                        trace.statement("local_4a8 = 0x93fd561a96ab0c67;");
                                                                        trace.statement("plVar16 = (longlong *)FUN_180241a30(&DAT_1803fadf0,local_1208,&local_4a8);");
                                                                        trace.statement("local_4a0 = 0xda04d326321e3cd7;");
                                                                        trace.statement("plVar16 = (longlong *)FUN_180241a30(*plVar16 + 0x28,local_11f8,&local_4a0);");
                                                                        trace.statement("uVar17 = FUN_1801fcfc0(*plVar16 + 0x28);");
                                                                        trace.statement("FUN_1801a0b60(\"Scrub Lua file paths (debug info)##fscloak_dbg\",uVar17);");
                                                                        trace.statement("cVar9 = FUN_18026ee60(0);");
                                                                        if (trace.checked_condition("if (cVar9 != '\\0')", [&]() -> bool { return static_cast<bool>(cVar9 != '\0'); })) {
                                                                            trace.statement("FUN_180280d00(");
                                                                            trace.statement("\"Every function carries the name of the file it came from, and\\ndebug.getinfo / debug.traceback / jit.util.funcinfo hand it over\\nwithout touching a single file API. Walk hook.GetTable() and you\\nhave a list of what is loaded on this client.\\n\\nWith this on, a function whose file matches a rule above reports\\nas a C function: source \\\"=[C]\\\", short_src \\\"[C]\\\", what \\\"C\\\",\\nline numbers -1 -- all of it together, because half a rewrite is\\nan impossible combination and a sharper tell than the leak.\\n\\nChunk names are spelled \\\"lua/<addon-subfolder>/...\\\" or\\n\\\"addons/<name>/...\\\", so the addons rule already covers the\\nsecond; add lua/<folder> for the first.\\n\\nTrade-off: an addon of yours that looks up its OWN path this way\\ngets [C] too. Error message text is not covered - only these\\nthree functions are.\"");
                                                                            trace.statement(");");
                                                                        }
                                                                        trace.statement("local_498 = 0x93fd561a96ab0c67;");
                                                                        trace.statement("plVar16 = (longlong *)FUN_180241a30(&DAT_1803fadf0,local_11e8,&local_498);");
                                                                        trace.statement("local_490 = 0x80462f2d9c85b9d;");
                                                                        trace.statement("plVar16 = (longlong *)FUN_180241a30(*plVar16 + 0x28,local_11d8,&local_490);");
                                                                        trace.statement("uVar17 = FUN_1801fcfc0(*plVar16 + 0x28);");
                                                                        trace.statement("FUN_1801a0b60(\"Hide workshop addons (engine.GetAddons)##fscloak_ws\",uVar17);");
                                                                        trace.statement("cVar9 = FUN_18026ee60(0);");
                                                                        if (trace.checked_condition("if (cVar9 != '\\0')", [&]() -> bool { return static_cast<bool>(cVar9 != '\0'); })) {
                                                                            trace.statement("FUN_180280d00(");
                                                                            trace.statement("\"engine.GetAddons() returns your whole workshop subscription --\\ntitle, wsid, size, mounted -- and never goes near the filesystem,\\nso nothing above touches it. Entries whose .gma sits under a\\ncloaked path are dropped.\\n\\n(!) With the default addons rule that empties the list, and some\\ngamemodes MOUNT CONTENT from it -- wOS dynabase (Z-City/Homigrad)\\nwalks GetAddons and calls game.MountGMA(addon.file) for models.\\nTurn this on only if you can live without that.\"");
                                                                            trace.statement(");");
                                                                        }
                                                                        trace.statement("local_488 = 0x93fd561a96ab0c67;");
                                                                        trace.statement("plVar16 = (longlong *)FUN_180241a30(&DAT_1803fadf0,local_11c8,&local_488);");
