                                                                        trace.statement("uVar17 = FUN_1801fcfc0(*plVar16 + 0x28);");
                                                                        trace.statement("FUN_1801a0b60(\"Hide other mounted games (engine.GetGames)##fscloak_games\",uVar17);");
                                                                        trace.statement("cVar9 = FUN_18026ee60(0);");
                                                                        if (trace.checked_condition("if (cVar9 != '\\0')", [&]() -> bool { return static_cast<bool>(cVar9 != '\0'); })) {
                                                                            trace.statement("FUN_180280d00(");
                                                                            trace.statement("\"Reports every game except garrysmod as not installed and not\\nmounted. This is a pure fingerprint input -- nova hashes exactly\\nthese flags into its device id.\\n\\nThe list itself is kept, only the flags are cleared: GMod\\'s set of\\nknown games is fixed, so an empty list is an anomaly while\\n\\\"owns nothing but the base game\\\" is the commonest setup there is.\"");
                                                                            trace.statement(");");
                                                                        }
